<div class="section-head"><div><h2>Contest approvals</h2><p class="muted">Review submitted contests before publication.</p></div></div><section class="grid"><?php foreach($contests as $c):?><article class="card"><div class="section-head"><div><h3><?=e($c['contest_title'])?></h3><p class="muted">By <?=e($c['organizer_name'])?> · <?=e($c['start_time'])?></p></div><span class="badge badge-pending_approval">Pending approval</span></div><p><?=e($c['description'])?></p><form method="post" action="<?=e(url('/admin/approvals/'.$c['contest_id']))?>" class="form-grid"><?=csrf_field()?><div class="field field-full"><label for="reason-<?=e($c['contest_id'])?>">Reason (required for rejection)</label><input id="reason-<?=e($c['contest_id'])?>" name="reason"></div><button class="button" name="decision" value="APPROVED">Approve</button><button class="button-danger" name="decision" value="REJECTED">Reject</button></form></article><?php endforeach;?><?php if(!$contests):?><article class="card empty">No contests await approval.</article><?php endif;?></section>
